def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def robTree(tree):
    val, left, right = parse(tree)
    n = len(val)
    take = [0] * n
    skip = [0] * n
    for u in range(n - 1, -1, -1):
        t = val[u]
        s = 0
        for c in (left[u], right[u]):
            if c != -1:
                t += skip[c]
                s += max(take[c], skip[c])
        take[u] = t
        skip[u] = s
    return max(take[0], skip[0])
